(() => {
  let time = parseInt(new Date().getTime() / 1000);
  let minuteTag = parseInt(time / 60) % 16;
  let bodyBgColor = "#1E1E1E";

  switch (minuteTag) {
    case 0:
      bodyBgColor = "#FFC0CB";
      break;
    case 1:
      bodyBgColor = "#F0F8FF";
      break;
    case 2:
      bodyBgColor = "#4169E1";
      break;
    case 3:
      bodyBgColor = "#4682B4";
      break;
    case 4:
      bodyBgColor = "#808000";
      break;
    case 5:
      bodyBgColor = "#FFDEAD";
      break;
    case 6:
      bodyBgColor = "#A0522D";
      break;
    case 7:
      bodyBgColor = "#7FFF00";
      break;
    case 8:
      bodyBgColor = "#FF69B4";
      break;
    case 9:
      bodyBgColor = "#F0FFFF";
      break;
    case 10:
      bodyBgColor = "#FFE4E1";
      break;
    case 11:
      bodyBgColor = "#EEEEEE";
      break;
    case 12:
      bodyBgColor = "#7CFC00";
      break;
    case 13:
      bodyBgColor = "#EEEEEE";
      break;
    case 14:
      bodyBgColor = "#FFA500";
      break;
    case 15:
      bodyBgColor = "#000080";
      break;
  }

  let el = document.getElementById("contentHtml");
  let styleEl = document.createElement("style");
  styleEl.innerHTML = "body{background-color:" + bodyBgColor + ";}";

  el.appendChild(styleEl);
})();
